import { readFileSync, existsSync } from "fs";
import path from "path";

interface PreviewFile {
  file_path: string;
  content: string;
  language?: string;
}

/**
 * Self-hosted LIVE preview.
 *
 * React + Babel are read from YOUR OWN node_modules and inlined as base64,
 * so there is NO external CDN and NO /public/preview/vendor folder to forget
 * to create. That removes the "preview loads forever" failure mode (a missing
 * vendor script could never define React/Babel, so the page just hung).
 *
 * The generated HTML implements a tiny in-browser module system so multi-file
 * apps (app/page.tsx importing components/Logo.tsx, etc.) actually render.
 * Next.js-only APIs and unknown UI libraries are stubbed so they don't crash.
 */

// ---- vendor bundles (read once per server process) -------------------------
let VENDOR: { react: string; reactDOM: string; babel: string } | null = null;
let VENDOR_ERROR: string | null = null;

// React 19 (Next's version) removed the UMD builds, so we embed React 18's UMD
// directly as base64. This means the preview depends on NOTHING external: no
// CDN, no /public/preview/vendor folder, no npm alias, no peer conflicts.
// Babel is read from node_modules/@babel/standalone (already installed, no conflict).
const REACT_18_B64 = "";
const REACT_DOM_18_B64 = "";

function loadVendor() {
  if (VENDOR || VENDOR_ERROR) return;

  const root = process.cwd();
  const babelPath = path.join(root, "node_modules/@babel/standalone/babel.min.js");
  if (!existsSync(babelPath)) {
    VENDOR_ERROR =
      "Missing: @babel/standalone. Run this ONCE in the project folder:\n" +
      "npm i -D @babel/standalone";
    return;
  }

  VENDOR = {
    react: Buffer.from(REACT_18_B64, "base64").toString("utf8"),
    reactDOM: Buffer.from(REACT_DOM_18_B64, "base64").toString("utf8"),
    babel: readFileSync(babelPath, "utf8"),
  };
}

function b64(s: string): string {
  return Buffer.from(s, "utf8").toString("base64");
}

// ---- browser-side loader (decodes + evals the inlined UMD bundles) ----------
const VENDOR_LOADER = String.raw`
(function () {
  if (typeof self === "undefined") self = window;
  if (typeof globalThis === "undefined") globalThis = window;
  function b64decode(b64) {
    var bin = atob(b64);
    var bytes = new Uint8Array(bin.length);
    for (var i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
    return new TextDecoder("utf-8").decode(bytes);
  }
  function run(b64) {
    try { new Function(b64decode(b64))(); } catch (e) { console.error("vendor load error", e); }
  }
  var v = window.__VENDOR__ || {};
  if (v.react) run(v.react);
  if (v.reactDOM) run(v.reactDOM);
  if (v.babel) run(v.babel);
})();
`;

// ---- browser-side runtime (module system + render) -------------------------
const RUNTIME_JS = String.raw`
(function () {
  function showError(title, detail) {
    var root = document.getElementById("root");
    if (!root) return;
    root.innerHTML =
      '<div style="padding:28px;color:#b91c1c;font-family:ui-sans-serif,system-ui,sans-serif;max-width:860px;margin:0 auto">' +
      '<h2 style="margin:0 0 8px">' + (title || "Preview error") + "</h2>" +
      (detail ? '<pre style="background:#f1f5f9;color:#334155;padding:14px;border-radius:8px;white-space:pre-wrap;overflow:auto;font-size:12px">' + detail + "</pre>" : "") +
      "</div>";
  }

  function showInfo(title, detail) {
    var root = document.getElementById("root");
    if (!root) return;
    root.innerHTML =
      '<div style="padding:40px;color:#475569;font-family:ui-sans-serif,system-ui,sans-serif;max-width:640px;margin:0 auto;text-align:center">' +
      '<div style="font-size:34px;margin-bottom:12px">🧠</div>' +
      '<h2 style="margin:0 0 10px;color:#1e293b;font-weight:600">' + (title || "Nothing to preview yet") + "</h2>" +
      (detail ? '<p style="color:#64748b;line-height:1.5;margin:0">' + detail + "</p>" : "") +
      "</div>";
  }

  if (typeof React === "undefined" || typeof ReactDOM === "undefined" || typeof Babel === "undefined") {
    showError("Preview engine failed to load",
      "React / ReactDOM / Babel were not found. Make sure react, react-dom and @babel/standalone are installed, then restart the dev server.");
    return;
  }

  var files = window.__FILES__ || [];

  function norm(p) {
    p = (p || "").replace(/\\/g, "/");
    p = p.replace(/^\.\//, "").replace(/^\//, "").replace(/^src\//, "");
    p = p.replace(/\.(tsx|ts|jsx|js|mjs)$/, "");
    return p;
  }

  var codeReg = {};
  var jsonReg = {};
  files.forEach(function (f) {
    var fp = f.file_path || "";
    var l = fp.toLowerCase();
    if (/\.(tsx|ts|jsx|js|mjs)$/.test(l)) codeReg[norm(fp)] = f.content;
    else if (/\.json$/.test(l)) jsonReg[norm(fp)] = f.content;
  });

  function resolve(spec, fromId) {
    if (spec.indexOf("@/") === 0) return norm(spec.slice(2));
    if (spec.indexOf("~/") === 0) return norm(spec.slice(2));
    if (spec.indexOf(".") !== 0) return spec; // bare library
    var base = fromId.indexOf("/") >= 0 ? fromId.slice(0, fromId.lastIndexOf("/")) : "";
    var parts = (base ? base.split("/") : []).concat(spec.split("/"));
    var out = [];
    for (var i = 0; i < parts.length; i++) {
      var p = parts[i];
      if (p === "." || p === "") continue;
      if (p === "..") out.pop(); else out.push(p);
    }
    return out.join("/");
  }

  // Recursive stub for unknown libraries so they never crash the preview.
  // Renders a small visible placeholder so you can SEE what was stubbed.
  var MARKER_STYLE = {
    display: "inline-block", padding: "2px 5px", margin: "2px",
    border: "1px dashed #cbd5e1", borderRadius: "4px",
    fontSize: "10px", color: "#94a3b8", background: "#f8fafc"
  };
  function makeStub(name) {
    var C = function () { return null; };
    C.displayName = name;
    return new Proxy(C, {
      get: function (t, prop) {
        if (prop === "default") return C;
        if (prop === "__esModule") return true;
        if (prop === "displayName" || prop === "name") return name;
        if (prop === "toString" || prop === "valueOf") return function () { return name; };
        if (prop === "then") return undefined;       // never a thenable
        if (prop === "prototype") return undefined;  // treat as function component
        // Don't let React mistake these probes for real props/objects.
        if (prop === "propTypes" || prop === "contextTypes" || prop === "defaultProps" ||
            prop === "getDefaultProps" || prop === "getDerivedStateFromProps" ||
            prop === "childContextTypes" || prop === "contextType" ||
            prop === "arguments" || prop === "caller" || prop === "callee" || prop === "length") {
          return undefined;
        }
        if (typeof prop === "symbol") {
          if (prop === Symbol.toPrimitive) return function () { return name; };
          if (prop === Symbol.toStringTag) return name;
          return undefined;
        }
        return makeStub(name + "." + String(prop));
      },
      apply: function (t, thisArg, args) {
        var props = (args && args[0]) || {};
        return React.createElement("span",
          Object.assign({}, props, { title: name, style: MARKER_STYLE }),
          props.children || name);
      }
    });
  }

  var cache = {};
  var compiled = {};

  // Babel's CommonJS transform expects ESM-shaped modules. UMD bundles
  // (React/ReactDOM) expose their API as non-enumerable properties, so a plain
  // spread/for-in would drop nearly everything (useState, createElement, ...).
  // Delegate ALL access to the real module via a Proxy instead.
  function interop(mod) {
    if (mod && mod.__esModule && mod.default) return mod;
    var target = mod || {};
    return new Proxy(target, {
      get: function (t, prop) {
        if (prop === "default") return mod;
        if (prop === "__esModule") return true;
        return target[prop];
      },
      apply: function (t, thisArg, args) {
        return (mod || function () {}).apply(thisArg, args);
      },
      construct: function (t, args) {
        return new (mod || function () {})();
      },
    });
  }

  function makeRequire(fromId) {
    return function (req) {
      var id = resolve(req, fromId);
      if (codeReg[id] !== undefined || jsonReg[id] !== undefined) return load(id);
      if (req === "react") return interop(React);
      if (req === "react-dom" || req === "react-dom/client") return interop(ReactDOM);
      if (req === "next/link") return { default: function (p) { return React.createElement("a", p); }, __esModule: true };
      if (req === "next/image") return { default: function (p) { return React.createElement("img", p); }, __esModule: true };
      if (req === "next/head") return { default: function () { return null; }, __esModule: true };
      if (req === "next/navigation") return {
        useRouter: function () { return { push: function () {}, back: function () {}, pathname: "/" }; },
        usePathname: function () { return "/"; },
        useSearchParams: function () { return {}; }
      };
      return makeStub(req);
    };
  }

  function compile(id) {
    if (compiled[id]) return compiled[id];
    var src = codeReg[id];
    // Try several Babel configs so we work across @babel/standalone versions.
    // (Babel 8 removed isTSX/allExtensions/allowDeclareFields; runtime must be
    // "classic" so JSX becomes React.createElement for the preview's React global.)
    var configs = [
      { presets: [["typescript", {}], ["react", { runtime: "classic" }]], plugins: [["transform-modules-commonjs", { noInterop: true }]] },
      { presets: [["typescript", { isTSX: true, allExtensions: true }], ["react", { runtime: "classic" }]], plugins: [["transform-modules-commonjs", { noInterop: true }]] },
      { presets: ["typescript", "react"], plugins: [["transform-modules-commonjs", { noInterop: true }]] },
    ];
    var lastErr;
    for (var ci = 0; ci < configs.length; ci++) {
      try {
        var code = Babel.transform(src, Object.assign({ filename: id + ".tsx" }, configs[ci])).code;
        // Reject automatic-runtime output (needs react/jsx-runtime) in favour of a classic config.
        if (code && code.indexOf("jsx-runtime") === -1) {
          compiled[id] = code;
          return code;
        }
        lastErr = new Error("Babel produced jsx-runtime output (unexpected)");
      } catch (e) { lastErr = e; }
    }
    throw lastErr;
  }

  function load(id) {
    if (cache[id]) return cache[id].exports;
    if (jsonReg[id] !== undefined) {
      var j = { exports: JSON.parse(jsonReg[id]) };
      cache[id] = j;
      return j.exports;
    }
    var moduleObj = { exports: {} };
    cache[id] = moduleObj;
    var code = compile(id);
    var fn = new Function("require", "module", "exports", "React", "ReactDOM", code);
    fn(makeRequire(id), moduleObj, moduleObj.exports, React, ReactDOM);
    return moduleObj.exports;
  }

  function findEntry() {
    var cands = ["app/page", "src/app/page"];
    for (var i = 0; i < cands.length; i++) if (codeReg[cands[i]] !== undefined) return cands[i];
    var pages = Object.keys(codeReg).filter(function (k) { return /\/page$/.test(k); });
    if (pages.length) return pages.sort()[0];
    var all = Object.keys(codeReg);
    return all.length ? all[0] : null;
  }

  // Watchdog: if nothing rendered in time, show a clear message (never spin).
  setTimeout(function () {
    if (!window.__RENDERED__ && !window.__NO_ENTRY__) {
      showError("Preview is taking too long",
        "The component may contain an infinite loop, or a Next.js-only API that is not stubbed. Paste the red error from the preview's browser console and I will fix it.");
    }
  }, 10000);

  try {
    var eid = findEntry();
    if (!eid) {
      window.__NO_ENTRY__ = true;
      showInfo("Your live preview will appear here", "Ask Shang Tsung to build your first screen — for example: \"Create a landing page with a hero section and a pricing table.\" Once he creates app/page.tsx, it shows up here automatically.");
      return;
    }
    var entry = load(eid);
    var Page = entry.default || entry;
    if (typeof Page !== "function") throw new Error('Entry "' + eid + '" did not export a React component.');
    var root = ReactDOM.createRoot(document.getElementById("root"));
    root.render(React.createElement(Page));
    window.__RENDERED__ = true;
  } catch (err) {
    showError("Preview could not render this screen", (err && err.message) ? err.message : String(err));
  }
})();
`;

export function generatePreviewHTML(input: { files: PreviewFile[] }): string {
  const files = input.files || [];

  loadVendor();

  if (VENDOR_ERROR || !VENDOR) {
    const msg = VENDOR_ERROR || "Unknown preview setup error.";
    return `<!DOCTYPE html>
<html lang="en"><head><meta charset="utf-8" />
<title>Live App Preview</title>
<style>html,body{margin:0;padding:0;font-family:ui-sans-serif,system-ui,sans-serif;background:#0f172a;color:#e2e8f0}</style>
</head><body>
<div style="padding:32px;max-width:760px;margin:0 auto">
  <h2 style="color:#f87171">Live preview could not start</h2>
  <p style="color:#cbd5e1">${msg.replace(/</g, "&lt;")}</p>
  <p style="color:#94a3b8">This is a one-time setup step. After installing, restart the dev server and reload the preview.</p>
</div>
</body></html>`;
  }

  const vendorJSON = JSON.stringify({
    react: b64(VENDOR.react),
    reactDOM: b64(VENDOR.reactDOM),
    babel: b64(VENDOR.babel),
  });

  // Escape < so a file containing </script> cannot break the inline JSON.
  const filesJSON = JSON.stringify(
    files.map((f) => ({ file_path: f.file_path, content: f.content }))
  ).replace(/</g, "\\u003c");

  return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width, initial-scale=1" />
<title>Live App Preview</title>
<!-- Tailwind Play CDN: styles the Tailwind utility classes Shang Tsung uses.
     Needs an internet connection. -->
<script src="https://cdn.tailwindcss.com"></script>
<style>
  html,body{margin:0;padding:0;font-family:ui-sans-serif,system-ui,sans-serif;background:#fff;color:#0f172a}
  *{box-sizing:border-box}
  #root{min-height:100vh}
  .abs-loader{display:flex;align-items:center;justify-content:center;min-height:100vh;color:#64748b;gap:12px}
  .abs-spin{width:22px;height:22px;border:3px solid #e2e8f0;border-top-color:#7c3aed;border-radius:50%;animation:abs-spin 0.8s linear infinite}
  @keyframes abs-spin{to{transform:rotate(360deg)}}
</style>
</head>
<body>
<div id="root"><div class="abs-loader"><div class="abs-spin"></div><span>Rendering live preview…</span></div></div>
<script>window.__VENDOR__ = ${vendorJSON}; window.__FILES__ = ${filesJSON};</script>
<script>${VENDOR_LOADER}</script>
<script>${RUNTIME_JS}</script>
</body>
</html>`;
}
